using System.Text.Json;

internal sealed record SimPartRequestUpload(string ExpectedToken,string RequestId,string? UpdateId=null);
internal sealed record SimEstimatePartRoute(int Index,string Find,string? ProposedPartNumber,string Status,string RequestId,bool AllowedForEstimate,string Reason,string? BasisReference);

internal sealed partial class SimRfqIntakeStore
{
    private static bool PartCanSubmit(SimPersona p)=>p.IsActive&&p.Can("rfq.part_requests.create");
    private static bool PartRequestOwner(SimMaterialPartBatch b,SimPersona p)=>p.Can("technical_review.disposition")||b.SubmittedBy.Id==p.Id;
    private static bool PartEstimateAllowed(SimMaterialPartBatch b,SimMaterialPartActions a){var updated=a.History.LastOrDefault(h=>h.Update is not null)?.Version??0;return b.Purpose=="INTERNAL_BOM_UPDATE"&&(updated==0?b.ContractVersion==2||b.ContractVersion==3&&a.History.Any(h=>h.Action=="ALLOW_ESTIMATE"):a.History.Any(h=>h.Action=="ALLOW_ESTIMATE"&&h.Version>updated));}
    private static string PartRequirementsHash(SimRfqIntakeRecord r)=>PartHash(new{r.CustomerRequirements,r.ContractReview});
    private static string[] PartRequirements(SimRfqIntakeRecord r)=>r.CustomerRequirements.Concat(r.ContractReview is null?[]:new[]{"Review the recorded customer contract requirements before choosing internal resolution."}).ToArray();
    private async Task<bool> PartCanEdit(string id){try{var r=await RequireRfqRecord(id);var lane=(await ReadRfqLanes()).GetValueOrDefault(id);return QuotationEditBlocker(r.IntakeId,lane?.Commercial,(await ReadDatasetAsync()).Records) is null;}catch(Exception e)when(e is SimRfqIntakeProblem or IOException or UnauthorizedAccessException){return false;}}
    private static IEnumerable<SimMaterialAttachment> PartAttachments(SimMaterialPartBatch b)=>b.Items.SelectMany(i=>i.Evidence.Attachments).Concat(b.RequestEvidence?.Attachments??[]).GroupBy(a=>a.DocumentId).Select(g=>g.First());
    private static SimMaterialPartEvidenceView? PartRequestEvidenceView(SimMaterialPartBatch b,string scope)=>b.RequestEvidence is null?null:new(b.RequestEvidence.Notes,b.RequestEvidence.Attachments.Select(a=>new SimMaterialPartAttachmentView(a.DocumentId,a.Owner,a.Kind,a.Category,a.Name,a.Type,a.Size,a.Sha256,a.AddedBy,a.AddedAt,PartEvidenceUrl(scope,b.RfqId,b.Id,a.DocumentId))).ToArray());
    private string PartArchivePath(string hash){PartRequire(System.Text.RegularExpressions.Regex.IsMatch(hash,"^[A-F0-9]{64}$"),"PART_REQUEST_EVIDENCE","Invalid evidence identity.");return Path.Combine(MaterialPartRoot,"evidence",hash);}
    private async Task<byte[]> ArchivedPartBytes(SimMaterialAttachment a){var bytes=await File.ReadAllBytesAsync(PartArchivePath(a.Sha256));PartRequire(bytes.LongLength==a.Size&&PartHashBytes(bytes)==a.Sha256,"PART_REQUEST_EVIDENCE","Archived request evidence could not be verified.");return bytes;}
    private static string PartHashBytes(byte[] b)=>SimLibraryBomStore.Hash(b);
    private async Task ArchivePartEvidence(SimRfqIntakeRecord r,IEnumerable<SimMaterialAttachment> attachments){
        foreach(var a in attachments){var trusted=await VerifiedMaterialAttachment(r,a.DocumentId);PartRequire(trusted==a,"PART_REQUEST_EVIDENCE","Evidence changed before this request was saved.");var bytes=await documents.Bytes(r.RequestCorrelationId,a.DocumentId);var path=PartArchivePath(a.Sha256);Directory.CreateDirectory(Path.GetDirectoryName(path)!);if(!File.Exists(path)){var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllBytesAsync(temp,bytes);try{File.Move(temp,path,false);}catch(IOException)when(File.Exists(path)){} }finally{if(File.Exists(temp))File.Delete(temp);}}_=await ArchivedPartBytes(a);}
    }
    private async Task<bool> PartHasResponse(string id){foreach(var child in (await PartBatches()).Where(b=>b.ParentBatchId==id)){var actions=await ReadPartActions(child);if(!actions.History.Any(a=>a.Action=="CANCEL"))return true;}return false;}
    internal async Task<SimMaterialAttachment> StagePartRequestEvidence(string id,SimPartRequestUpload request,string name,Stream input,SimPersona persona){
        PartPermission(persona,"materials",true);await gate.WaitAsync();try{
            _=PartBatchPath(request.RequestId);string owner="part-request:"+request.RequestId;
            if(File.Exists(PartBatchPath(request.RequestId))){var existing=await ReadPartBatch(request.RequestId);var current=await PartView(existing,"materials",persona);PartRequire(existing.RfqId==id&&current.CanUpdate&&Guid.TryParseExact(request.UpdateId,"D",out _),"PART_REQUEST_FIXED","This request cannot be updated here.");PartRequire(request.ExpectedToken==current.Token,"PART_REQUEST_STALE","This request changed. Reopen it before attaching evidence.");owner="part-request-update:"+request.RequestId+":"+request.UpdateId;}
            else PartRequire(request.UpdateId is null,"PART_REQUEST_SCOPE","Choose a saved request for this update.");
            PartRequire(await PartCanEdit(id),"PART_REQUEST_COMMITTED","This quotation is no longer editable here.");var source=await PartSource(id,persona);if(request.UpdateId is null)PartRequire(source.Token==request.ExpectedToken,"PART_REQUEST_STALE","Materials changed. Reopen the current request before attaching evidence.");
            PartRequire(new[]{".pdf",".xls",".xlsx",".doc",".docx",".txt",".csv",".png",".jpg",".jpeg"}.Contains(Path.GetExtension(name).ToLowerInvariant()),"PART_REQUEST_EVIDENCE_TYPE","Choose PDF, Office, text, CSV or image evidence.");
            var r=await RequireRfqRecord(id);var doc=await documents.Stage(r.RequestCorrelationId,name,0,input,persona.DisplayName);var bytes=await documents.Bytes(r.RequestCorrelationId,doc.DocumentId!);
            var attachment=new SimMaterialAttachment(doc.DocumentId!,id,owner,"FILE","SUPPORTING_DOCUMENT",doc.Name,doc.Type,bytes.Length,PartHashBytes(bytes),doc.DocumentReference!,persona.DisplayName,DateTimeOffset.UtcNow);
            await documents.WriteMaterialAttachment(r.RequestCorrelationId,attachment);return attachment;
        }finally{gate.Release();}
    }
    private async Task<SimMaterialPartBatchView> CreateRoutedPartRequest(string id,SimMaterialPartCreate request,SimPersona persona){
        await gate.WaitAsync();try{
            _=PartBatchPath(request.RequestId);PartRequire(request.Route is "INTERNAL_BOM_UPDATE" or "CUSTOMER","PART_REQUEST_ROUTE","Choose Internal BOM update or Ask customer.");
            var commandHash=PartHash(request);if(File.Exists(PartBatchPath(request.RequestId))){var prior=await ReadPartBatch(request.RequestId);PartRequire(prior.RfqId==id&&prior.RequestHash==commandHash&&prior.SubmittedBy.Id==persona.Id,"PART_REQUEST_REPLAY","This request reference already contains different content. Reopen saved requests.");return await PartView(prior,"materials",persona);}
            PartRequire(await PartCanEdit(id),"PART_REQUEST_COMMITTED","This quotation is no longer editable here.");var source=await PartSource(id,persona);var r=await RequireRfqRecord(id);var material=MaterialView(RfqView(r,await ReadRfqLanes()));
            PartRequire(request.Indexes is {Length:>0 and <=1000}&&request.Indexes.Distinct().Count()==request.Indexes.Length&&request.Indexes.All(i=>source.Items.Any(s=>s.Index==i)),"PART_REQUEST_ROWS","Select currently flagged parts.");
            var note=PartText(request.Note,2000,"Reason");PartRequire(note.Length>0,"PART_REQUEST_REASON","Enter the reason for this request.");var reference=PartText(request.BasisReference,4000,"Evidence reference");
            var internalRoute=request.Route=="INTERNAL_BOM_UPDATE";
            var selected=PartItems(material,source.Baseline).Where(i=>request.Indexes.Contains(i.Index)).OrderBy(i=>i.Index).ToArray();
            PartRequire(!internalRoute||selected.All(i=>i.Intent=="PROPOSED_PART"&&!string.IsNullOrWhiteSpace(i.QuotedPartNumber)),"PART_REQUEST_UNRESOLVED","An unidentified alternate cannot be internally resolved. Enter a supported proposed P/N or ask the customer.");
            var files=new List<SimMaterialAttachment>();var ids=request.AttachmentIds??[];PartRequire(ids.Length<=20&&ids.Distinct().Count()==ids.Length,"PART_REQUEST_EVIDENCE","Use up to 20 distinct request attachments.");
            foreach(var docId in ids){var a=await VerifiedMaterialAttachment(r,docId);PartRequire(a.Owner=="part-request:"+request.RequestId&&!a.Removed,"PART_REQUEST_EVIDENCE","Choose evidence uploaded for this request.");files.Add(a);}
            SimMaterialPartBatch? parent=null;
            if(request.ParentBatchId is not null){parent=await ReadPartBatch(request.ParentBatchId);PartRequire(internalRoute&&parent.RfqId==id&&parent.Purpose=="ASK_CUSTOMER"&&parent.Items.Select(i=>i.Index).Order().SequenceEqual(selected.Select(i=>i.Index).Order()),"PART_REQUEST_RESPONSE","Choose the same customer-request items for the supported response.");PartRequire(files.Count>0||reference.Length>0,"PART_REQUEST_RESPONSE","Attach the usable customer response or record its evidence reference before routing it.");}
            SimMaterialPartRecipient recipient;
            if(internalRoute)recipient=(await PartRecipients()).SingleOrDefault(p=>p.Id==(request.RecipientId??MaterialPartTeam))??throw SimRfqIntakeProblem.BadRequest("PART_REQUEST_RECIPIENT","Choose an active Technical Review recipient.");
            else{string name=PartText(request.RecipientName,200,"Recipient"),address=PartText(request.RecipientAddress,500,"Destination");PartRequire(name.Length>0&&address.Length>0,"PART_REQUEST_RECIPIENT","Enter the customer recipient and destination.");recipient=new(null,name,address);}
            var purpose=internalRoute?"INTERNAL_BOM_UPDATE":"ASK_CUSTOMER";
            foreach(var prior in (await PartBatches()).Where(b=>b.RfqId==id)){
                var v=await PartView(prior,"materials",persona);if(!v.Current||v.Status is "CANCELLED" or "SUPERSEDED" or "RESPONSE_ROUTED"||prior.Id==request.ParentBatchId)continue;
                if(!prior.Items.Any(i=>selected.Any(s=>s.Index==i.Index)))continue;
                var same=prior.Purpose==purpose&&prior.ParentBatchId==request.ParentBatchId&&prior.SubmittedBy.Id==persona.Id&&v.Note==note&&(v.BasisReference??"")==reference&&prior.Recipient==recipient&&prior.Items.Select(i=>i.CurrentItemToken).SequenceEqual(selected.Select(i=>i.CurrentItemToken))&&(v.RequestEvidence?.Attachments??[]).Select(a=>a.Sha256).Order().SequenceEqual(files.Select(a=>a.Sha256).Order());
                if(same)return v;throw SimRfqIntakeProblem.Conflict("PART_REQUEST_ACTIVE","These items already have an active request. Open it or cancel it before changing their route.");
            }
            PartRequire(request.ExpectedToken==source.Token,"PART_REQUEST_STALE","Materials, evidence or requests changed. Reopen the current review.");
            if(parent is not null){var p=await PartView(parent,"materials",persona);PartRequire(p.CanRespond,"PART_REQUEST_RESPONSE","The customer request changed, was cancelled, or already has a routed response.");}
            var batch=new SimMaterialPartBatch(request.RequestId,persona.Can("technical_review.disposition")&&!request.ReviewOnly?2:3,commandHash,id,source.DisplayId,r.RequestCorrelationId,source.Customer,source.AssemblyNumber,source.Revision,source.Baseline,source.PlanRevision,internalRoute?"TECHNICAL_REVIEW":"CUSTOMER",recipient,note,selected,new(persona.Id,persona.DisplayName),DateTimeOffset.UtcNow,"",purpose,reference.Length==0?null:reference,new([],files.ToArray()),request.ParentBatchId,null);
            await ArchivePartEvidence(r,PartAttachments(batch));batch=batch with{ContentHash=PartBatchHash(batch)};await WritePartRecord(PartBatchPath(batch.Id),batch,false);return await PartView(batch,"materials",persona);
        }finally{gate.Release();}
    }
    internal async Task<SimMaterialPartBatchView> CancelPartRequest(string id,string batchId,SimMaterialPartActionRequest request,SimPersona persona){
        PartPermission(persona,"materials",true);await gate.WaitAsync();try{var batch=await ReadPartBatch(batchId);PartRequire(batch.RfqId==id&&batch.ContractVersion>=2&&request.Action=="CANCEL","PART_REQUEST_SCOPE","Choose a request belonging to this RFQ.");var actions=await ReadPartActions(batch);var view=await PartView(batch,"materials",persona);if(actions.History.LastOrDefault() is {} last&&last.Action=="CANCEL"&&last.ExpectedToken==request.ExpectedToken&&last.Actor.Id==persona.Id)return view;PartRequire(request.ExpectedToken==view.Token&&view.CanCancel,"PART_REQUEST_STALE","This request changed or cannot be cancelled here.");var next=actions with{History=[..actions.History,new(actions.History.Length+1,"CANCEL",PartText(request.Note,2000,"Cancellation note"),new(persona.Id,persona.DisplayName),DateTimeOffset.UtcNow,request.ExpectedToken)]};next=next with{ContentHash=PartActionHash(next)};await WritePartRecord(PartActionPath(batchId),next,true);return await PartView(batch,"materials",persona);}finally{gate.Release();}
    }
    private async Task<SimEstimatePartRoute[]> PartEstimateRoutes(SimRfqIntakeRecord r,SimRfqLanes lanes){
        if(r.DeLeonScope=="LABOR_ONLY")return [];var material=MaterialView(RfqView(r,new Dictionary<string,SimRfqLanes>{{r.IntakeId,lanes}}));var baseline=PartBaseline(r,material);var current=PartItems(material,baseline);var result=new Dictionary<int,SimEstimatePartRoute>();
        foreach(var b in (await PartBatches()).Where(b=>b.RfqId==r.IntakeId&&b.ContractVersion>=2).OrderBy(b=>b.SubmittedAtUtc)){if(PartHash(b.Baseline)!=PartHash(baseline)||b.Items.Any(i=>!current.Any(c=>c.Index==i.Index&&c.CurrentItemToken==i.CurrentItemToken)))continue;var actions=await ReadPartActions(b);if(actions.History.Any(a=>a.Action=="CANCEL")||PartStatus(b,actions)=="RETURNED_TO_MATERIALS")continue;if(b.Route=="CUSTOMER"&&await PartHasResponse(b.Id))continue;
            foreach(var item in b.Items.Where(i=>current.Any(c=>c.Index==i.Index&&c.CurrentItemToken==i.CurrentItemToken))){var allowed=PartEstimateAllowed(b,actions);var content=PartCurrentContent(b,actions);result[item.Index]=new(item.Index,item.Find,item.QuotedPartNumber,allowed?"Allowed for estimate · BOM update pending":b.Route=="TECHNICAL_REVIEW"?"Approval requested · Technical Review pending":"Customer response required",b.Id,allowed,content.Note,content.BasisReference);}}
        return result.Values.OrderBy(v=>v.Index).ToArray();
    }
}

internal static partial class SimRfqIntakeEndpoints
{
    private static void MapMaterialPartRouting(WebApplication app,SimStateStore state,SimRfqIntakeStore store,SimPersonaSessionStore personas){
        app.MapPost("/api/sim/rfqs/{id}/materials/part-requests/evidence",async Task<IResult>(string id,HttpContext c)=>{
            var denied=DeniedTechnicalReview(c,state,personas,"rfq.part_requests.create");if(denied is not null)return denied;if(!c.Request.Headers.ContainsKey("X-SIM-Document-Upload")||!c.Request.HasFormContentType)return Results.BadRequest();try{if(c.Request.ContentLength>21*1024*1024)return Results.StatusCode(413);var form=await c.Request.ReadFormAsync(new Microsoft.AspNetCore.Http.Features.FormOptions{MultipartBodyLengthLimit=21*1024*1024,ValueLengthLimit=4096});if(form.Files.Count!=1)return Results.BadRequest();var request=JsonSerializer.Deserialize<SimPartRequestUpload>(form["metadata"].ToString(),new JsonSerializerOptions(JsonSerializerDefaults.Web));if(request is null)return Results.BadRequest();var file=form.Files[0];await using var input=file.OpenReadStream();return Results.Json(await store.StagePartRequestEvidence(id,request,file.FileName,input,personas.Resolve(c)));}catch(SimRfqIntakeProblem p){return Results.Json(new{code=p.Code,message=p.Message},statusCode:p.StatusCode);}catch(LibraryBomPermissionException){return Results.StatusCode(403);}catch(Exception e)when(e is JsonException or InvalidDataException){return Results.BadRequest(new{message="Choose one supported file up to 20 MB."});}catch(Exception e)when(e is IOException or UnauthorizedAccessException){return Results.Json(new{message="Evidence could not be retained. Existing requests were preserved."},statusCode:503);}});
        app.MapPost("/api/sim/rfqs/{id}/materials/part-requests/{batchId}/update",async Task<IResult>(string id,string batchId,SimMaterialPartUpdateRequest request,HttpContext c)=>{var denied=DeniedTechnicalReview(c,state,personas,"rfq.part_requests.create");if(denied is not null)return denied;try{return Results.Json(await store.UpdateMaterialPartRequest(id,batchId,request,personas.Resolve(c)));}catch(SimRfqIntakeProblem p){return Results.Json(new{code=p.Code,message=p.Message},statusCode:p.StatusCode);}catch(LibraryBomPermissionException){return Results.StatusCode(403);}catch(Exception e)when(e is IOException or JsonException or UnauthorizedAccessException){return Results.Json(new{message="Update outcome is unconfirmed. Reopen this same request before retrying."},statusCode:503);}});
        app.MapPost("/api/sim/rfqs/{id}/materials/part-requests/{batchId}/actions",async Task<IResult>(string id,string batchId,SimMaterialPartActionRequest request,HttpContext c)=>{var denied=DeniedTechnicalReview(c,state,personas,"rfq.part_requests.create");if(denied is not null)return denied;try{return Results.Json(await store.CancelPartRequest(id,batchId,request,personas.Resolve(c)));}catch(SimRfqIntakeProblem p){return Results.Json(new{code=p.Code,message=p.Message},statusCode:p.StatusCode);}catch(LibraryBomPermissionException){return Results.StatusCode(403);}catch(Exception e)when(e is IOException or JsonException or UnauthorizedAccessException){return Results.Json(new{message="Cancellation outcome is unconfirmed. Check saved request status before retrying."},statusCode:503);}});
    }
}
